// SPDX-License-Identifier: CC0-1.0
// 262144要素の前後を独立なsort/multiset参照と照合する一時検証。
#ifndef EPQ_SOURCE
#define EPQ_SOURCE "baseline9ec.hpp"
#endif
#include EPQ_SOURCE
#include <algorithm>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <iterator>
#include <limits>
#include <set>
#include <source_location>
#include <type_traits>
#include <utility>
#include <vector>

static std::size_t checks = 0, pops = 0, cases = 0;
static void require(bool condition, std::source_location where = std::source_location::current()) {
    ++checks;
    if (!condition) {
        std::fprintf(stderr, "FAIL line=%u checks=%zu pops=%zu cases=%zu\n",
                     where.line(), checks, pops, cases);
        std::abort();
    }
}
constexpr std::size_t threshold = 262144;

template<class T>
static std::vector<T> make_values(std::size_t n, int pattern) {
    std::vector<T> result;
    result.reserve(n);
    for (std::size_t i = 0; i < n; ++i) {
        if (pattern == 2) result.push_back(T{7});
        else {
            const auto raw = pattern == 1 ? (i * 73 + 19) % 257 : (i * 1009 + 17) % n;
            if constexpr (std::is_signed_v<T>)
                result.push_back(static_cast<T>(raw) - static_cast<T>(n / 2));
            else result.push_back(static_cast<T>(raw));
        }
    }
    if (pattern != 2 && n >= 4) {
        result[0] = std::numeric_limits<T>::lowest();
        result[1] = std::numeric_limits<T>::max();
        result[2] = std::numeric_limits<T>::lowest();
        result[3] = std::numeric_limits<T>::max();
    }
    return result;
}

template<class T, bool Minimize>
static void threshold_cases() {
    using Q = ErasablePriorityQueue<T, Minimize>;
    for (int delta : {-1, 0, 1, 2, 3, 4, 5, 15, 16, 17}) {
        ++cases;
        const auto n = static_cast<std::size_t>(static_cast<std::int64_t>(threshold) + delta);
        const int pattern = (delta + 1) % 3;
        auto values = make_values<T>(n, pattern);
        auto sorted = values;
        std::sort(sorted.begin(), sorted.end());
        Q queue;
        if (delta & 1) for (const T value : values) queue.push(value);
        else queue = Q(std::move(values));
        require(queue.size() == n);
        // 代表2ケースだけ全drainし、他は必ず閾値の16個下まで進める。
        const auto count = delta == 2 || delta == 3 ? n : n - (threshold - 16);
        for (std::size_t i = 0; i < count; ++i) {
            const T expected = Minimize ? sorted[i] : sorted[n - i - 1];
            require(queue.top() == expected);
            if (i % 7 == 0) require(queue.try_top() == expected);
            if (i % 3 == 0) queue.pop();
            else require(queue.extract_top() == expected);
            ++pops;
            require(queue.size() == n - i - 1);
        }
        require(queue.empty() == (count == n));
        if (count == n) require(!queue.try_top() && !queue.extract_top());
        queue.clear(); require(queue.empty());
        queue.emplace(std::numeric_limits<T>::max());
        require(queue.extract_top() == std::numeric_limits<T>::max());
    }
}

template<class T, bool Minimize>
static void lazy_ownership() {
    using Q = ErasablePriorityQueue<T, Minimize>;
    for (int pattern = 0; pattern < 3; ++pattern) {
        ++cases;
        const auto n = threshold + 257;
        auto values = make_values<T>(n, pattern);
        Q queue(values);
        std::multiset<T> reference(values.begin(), values.end());
        // 先頭と内部の削除を溜め、物理サイズと論理サイズが異なる状態を作る。
        for (int i = 0; i < 17; ++i) {
            auto it = i < 8 ? (Minimize ? reference.begin() : std::prev(reference.end()))
                            : reference.find(values[1000 + i * 109]);
            require(it != reference.end());
            queue.erase(*it); reference.erase(it);
        }
        require(queue.size() == reference.size());
        Q copied(queue);
        Q assigned;
        assigned.emplace(T{42}); assigned = queue;
        Q moved(std::move(copied)); require(copied.empty());
        Q moved_assigned;
        moved_assigned = std::move(assigned); require(assigned.empty());
        moved_assigned.swap(moved);
        const auto initial_size = reference.size();
        // 同じ参照列で3所有者を確認し、通常popも閾値を跨ぐ。
        for (std::size_t i = 0; i < 512; ++i) {
            auto it = Minimize ? reference.begin() : std::prev(reference.end());
            const T expected = *it;
            for (Q* owner : {&queue, &moved, &moved_assigned}) {
                require(owner->top() == expected);
                require(owner->try_top() == expected);
                if (i % 2 == 0) require(owner->extract_top() == expected);
                else owner->pop();
                ++pops;
                require(owner->size() == initial_size - i - 1);
            }
            reference.erase(it);
        }
        queue.clear(); require(queue.empty());
        require(!moved.empty() && !moved_assigned.empty());
        const T expected = Minimize ? *reference.begin() : *reference.rbegin();
        require(moved.top() == expected && moved_assigned.top() == expected);
        copied.emplace(T{11}); require(copied.extract_top() == T{11});
        assigned.push(T{12}); require(assigned.extract_top() == T{12});
        moved.clear(); moved_assigned.clear();
        require(moved.empty() && moved_assigned.empty());
    }
}

template<class T, bool Minimize>
static void run() { threshold_cases<T, Minimize>(); lazy_ownership<T, Minimize>(); }
int main() {
    run<std::int64_t, true>(); run<std::int64_t, false>();
    run<std::uint64_t, true>(); run<std::uint64_t, false>();
    std::printf("ACTIVE PASS %zu checks; %zu pops; %zu cases\n", checks, pops, cases);
}
